cat > /tmp/s/plan.py <<'EOF'
import json,pathlib,re,shlex
A=pathlib.Path("/app/archive")
docs={p.stem:json.loads(p.read_text()) for p in A.glob("*.json")}
plan=[];N=0;T=0
for rid,d in sorted(docs.items()):
    if d.get("continuation_of"): continue
    args=[];flags=[]
    if d.get("v")==1:
        recs=[{"total_token_throughput":r[1]} for r in d.get("rows") or []]; args.append("--legacy-schema");flags.append("stale_schema")
    else: recs=list(d.get("results") or [])
    if d.get("continued_in"):
        o=docs[d["continued_in"]]; assert o["continuation_of"]==rid
        recs+=o.get("results") or []; args+=["--merge-with",d["continued_in"]];flags.append("split_sweep")
    bad=[i for i,r in enumerate(recs) if r.get("_truncated") or r.get("total_token_throughput") is None]
    if bad:
        assert bad==list(range(bad[0],len(recs))),(rid,bad)
        recs=recs[:bad[0]]; args+=["--truncate-at",str(bad[0])];flags.append("corrupt_tail")
    if d.get("v")!=1:
        if d.get("precision") is None:
            m=re.search(r"--quantization (\S+)"," ".join(d["log_lines"])); args+=["--precision",m.group(1)];flags.append("missing_precision")
        if d.get("gpu_count") is None:
            args+=["--gpus",str(len(d["visible_devices"]))];flags.append("ambiguous_gpu_count")
    N+=len(recs);T+=round(sum(r["total_token_throughput"] for r in recs),2)
    plan.append((rid,args,flags))
print(len(plan),N,round(T,2))
json.dump(plan,open("/tmp/s/plan.json","w"))
from collections import Counter;print(Counter(f for _,_,fl in plan for f in fl))
for p in plan:
    if p[1]: print(p)
